INSERT INTO blogs_description (blog_id, title, description, seo_description, language)
SELECT id, 'روکش زیرکونیا چیست؟ مزایا و محدودیت‌ها',
'<p>زیرکونیا مادهٔ سرامیکی بدون فلز است که در دندان‌پزشکی برای ساخت روکش و بریج به کار می‌رود. چون نور را به شکلی نزدیک به بافت طبیعی دندان عبور می‌دهد و مقاومت بالایی در برابر شکست دارد، هم در ناحیهٔ جلو و هم در ناحیهٔ عقب ارزیابی می‌شود. اما هیچ مادهٔ واحدی برای هر دهانی درست نیست: انتخاب بر پایهٔ جایگاه دندان، بافت سالم باقی‌مانده، بار اکلوزال و انتظار زیبایی انجام می‌گیرد.</p>
<h2>روکش زیرکونیا چیست؟</h2>
<p>ترمیمی است که روی زیرساختی بر پایهٔ اکسید زیرکونیوم و در صورت نیاز با لایه‌ای از پرسلن ساخته می‌شود. تفاوت اصلی آن با پرسلن فلزی، نداشتن زیرساخت فلزی است؛ از این رو خطر بازتاب خاکستری که می‌تواند به‌مرور در لبهٔ لثه دیده شود را ندارد.</p>
<p>زیرکونیا تنها یک نوع نیست. انواع شفاف‌تر در ناحیهٔ جلو برای زیبایی و انواع مقاوم‌تر در ناحیهٔ عقب برای بار جویدن ترجیح داده می‌شوند. اینکه کدام نوع به کار رود همراه با آزمایشگاه برنامه‌ریزی می‌گردد.</p>
<h2>در چه وضعیت‌هایی در نظر گرفته می‌شود؟</h2>
<ul>
<li>دندان‌هایی که مادهٔ بسیاری از دست داده‌اند و با ترمیم به‌اندازهٔ کافی پشتیبانی نمی‌شوند</li>
<li>دندان‌هایی که درمان ریشه شده‌اند و خطر شکستن‌شان افزایش یافته است</li>
<li>دندان‌های جلویی که تغییر رنگ و شکل‌شان از راه ترمیمی برنامه‌ریزی می‌شود</li>
<li>برنامه‌های بریج که در آن دندان از دست‌رفته با تکیه بر دندان‌های مجاور کامل می‌شود</li>
<li>کسانی که سابقهٔ حساسیت به فلز دارند</li>
<li>برنامه‌ریزی پروتز روی ایمپلنت — برای جزئیات <a href="/fa/dental-implant-tedavisi/">ایمپلنت دندانی</a></li>
</ul>
<h2>تفاوت زیرکونیا و e.max</h2>
<table>
<thead><tr><th>معیار</th><th>زیرکونیا</th><th>E.max (دی‌سیلیکات لیتیوم)</th></tr></thead>
<tbody>
<tr><td>ساختار</td><td>زیرساخت اکسید زیرکونیوم، در صورت نیاز لایهٔ پرسلن</td><td>سرامیک شیشه‌ای یک‌پارچه</td></tr>
<tr><td>شفافیت</td><td>بر پایهٔ نوع تغییر می‌کند؛ انواع بسیار شفاف هم هست</td><td>معمولاً شفاف‌تر</td></tr>
<tr><td>مقاومت</td><td>مقاومت بالاتر در برابر شکست</td><td>کمتر؛ در بریج‌های وسیع ترجیح داده نمی‌شود</td></tr>
<tr><td>کاربرد معمول</td><td>ناحیهٔ عقب، بریج، روی ایمپلنت</td><td>تک‌دندان در ناحیهٔ جلو، لمینت</td></tr>
</tbody>
</table>
<p>این مقایسه رتبه‌بندی برتری نیست. در یک دهان می‌توان برای ناحیهٔ جلو یک ماده و برای ناحیهٔ عقب مادهٔ دیگری برنامه‌ریزی کرد. برای کل برنامه‌ریزی زیبایی می‌توانید به صفحهٔ <a href="/fa/gulus-tasarimi/">طراحی لبخند فردی</a> نگاه کنید.</p>
<h2>مراحل آماده‌سازی و اجرا</h2>
<ol>
<li><strong>معاینه و برنامه‌ریزی.</strong> سلامت لثه، پوسیدگی، اکلوژن، عادت دندان‌قروچه و بافت سالم باقی‌مانده ارزیابی می‌شوند.</li>
<li><strong>آماده‌سازی مقدماتی.</strong> پوسیدگی و مشکلات لثه در صورت وجود برطرف می‌شوند؛ در صورت نیاز درمان ریشه کامل می‌گردد.</li>
<li><strong>آماده‌سازی دندان و قالب‌گیری.</strong> دندان به اندازه‌ای که مادهٔ انتخاب‌شده می‌طلبد تراشیده می‌شود؛ قالب یا اسکن دیجیتال گرفته می‌شود.</li>
<li><strong>ترمیم موقت.</strong> در طول مرحلهٔ آزمایشگاه دندان محافظت و شکل آزموده می‌شود.</li>
<li><strong>پروب و چسباندن.</strong> پس از بررسی تطابق، اکلوژن و رنگ، ثابت می‌شود.</li>
<li><strong>معاینه.</strong> در هفته‌های نخست تطابق و پاسخ لثه ارزیابی می‌گردد.</li>
</ol>
<h2>سازگاری با لثه و مراقبت</h2>
<p>نتیجهٔ بلندمدت روکش بیش از آنکه به ماده وابسته باشد، به تطابق لبه و مراقبت روزانه مربوط است. اگر ناحیه‌ای که لبهٔ روکش با لثه به هم می‌رسند تمیز نشود، آنجا التهاب و تغییر رنگ پدید می‌آید. از این رو استفاده از مسواک بین‌دندانی یا نخ دندان، تمیزکردن زیر بریج و معاینهٔ منظم بخشی از درمان‌اند.</p>
<p>در کسانی که عادت فشردن و سایش دندان دارند، نایت‌گارد می‌تواند مطرح شود. عادت‌هایی مانند شکستن پوستهٔ سفت با دندان و جویدن یخ خطر شکستن را هم در دندان طبیعی و هم در ترمیم افزایش می‌دهند.</p>
<h2>محدودیت‌هایی که باید دانست</h2>
<p>روکش زیرکونیا نیازمند تراشیدن بخشی از بافت دندان است؛ اقدامی است که بازگشت ندارد. از این رو نخست گزینه‌هایی که از دست رفتن بافت کمتری می‌خواهند (ترمیم، انله، لمینت) ارزیابی می‌شوند. اگر سفیدکردن قرار باشد انجام شود، ترتیب اهمیت دارد تا رنگ روکش بر همان پایه تعیین گردد؛ جزئیات در صفحهٔ <a href="/fa/dis-beyazlatma/">سفیدکردن دندان</a> است.</p>
<h2>پرسش‌های پرتکرار</h2>
<p><strong>روکش زیرکونیا چقدر دوام می‌آورد؟</strong><br>مدت از فردی به فرد دیگر تغییر می‌کند. تطابق لبه، سلامت لثه، بار اکلوزال، عادت فشردن دندان و مراقبت روزانه تعیین‌کننده‌اند. وعدهٔ عمری قطعی داده نمی‌شود.</p>
<p><strong>آیا پس از روکش حساسیت پدید می‌آید؟</strong><br>در روزهای نخست حساسیت به سرد و گرم ممکن است دیده شود و معمولاً فروکش می‌کند. در درد فزاینده یا طولانی معاینه لازم است.</p>
<p><strong>آیا رنگ روکش به‌مرور تغییر می‌کند؟</strong><br>رنگ خودِ زیرکونیا با سفیدکردن روشن نمی‌شود و به‌اندازهٔ دندان طبیعی با قهوه و چای رنگ نمی‌گیرد. لکه‌های تجمع‌یافته روی سطح اما با تمیزکردن برطرف می‌شوند.</p>
<p><strong>آیا برای هر دندانی زیرکونیا ساخته می‌شود؟</strong><br>خیر. اگر بافت سالم باقی‌مانده کافی باشد، نخست گزینه‌هایی که از دست رفتن بافت کمتری می‌خواهند مانند ترمیم یا انله ارزیابی می‌شوند.</p>
<p>در کلینیک ما در محل اتصال بیلیک‌دوزو/اسن‌یورت، تصمیم روکش پس از ارزیابی هم‌زمان سلامت لثه، اکلوژن و بافت سالم باقی‌مانده گرفته می‌شود.</p>
<p><a href="/fa/zirkonyum-dis-kaplama/">روکش زیرکونیا</a> &middot; <a href="/fa/estetik/">دندان‌پزشکی زیبایی</a> &middot; <a href="/fa/iletisim">نوبت و تماس</a></p>',
'روکش زیرکونیا چیست، در چه وضعیت‌هایی در نظر گرفته می‌شود و تفاوتش با e.max چیست؟ مراحل آماده‌سازی، سازگاری با لثه و نیاز به مراقبت.',
'FA' FROM blogs WHERE link = 'zirkonyum-dis-kaplama-nedir--avantajlari-nelerdir';

INSERT INTO blogs_description (blog_id, title, description, seo_description, language)
SELECT id, 'نشانه‌های زودهنگام بیماری‌های لثه و درمان آن‌ها',
'<p>بیماری‌های لثه بیشتر اوقات بدون درد آغاز می‌شوند. در مرحلهٔ نخست می‌تواند تنها خون‌ریزی‌ای باشد که هنگام مسواک‌زدن دیده می‌شود؛ از این رو تشخیص آن دیر می‌افتد. حال آنکه اگر در دورهٔ زودهنگام رسیدگی شود، تصویر تا اندازهٔ زیادی برگشت‌پذیر است. وقتی پیش برود، بافت استخوانی‌ای که دندان را نگه می‌دارد آسیب می‌بیند و از دست رفتن ماندگار می‌شود.</p>
<h2>نشانه‌های زودهنگام کدام‌اند؟</h2>
<ul>
<li><strong>خون‌ریزی:</strong> خون‌ریزی هنگام مسواک‌زدن یا استفاده از نخ دندان پرتکرارترین نشانهٔ نخست است. لثهٔ سالم با مسواک‌زدن خون‌ریزی نمی‌کند.</li>
<li><strong>قرمزی و ورم:</strong> لثهٔ سالم صورتی کم‌رنگ و سفت است. ظاهر قرمز روشن، متورم و نرم نشانهٔ التهاب است.</li>
<li><strong>تحلیل لثه:</strong> بلندتر دیده‌شدن دندان، آشکارشدن سطح ریشه و حساسیتی که همراه آن است.</li>
<li><strong>بوی دهان:</strong> باکتری‌هایی که در پاکت لثه جمع می‌شوند می‌توانند به بوی بد پایدار کمک کنند.</li>
<li><strong>بازشدن فاصله میان دندان‌ها:</strong> جابه‌جایی دندان‌ها، پدیدآمدن فاصله میان آن‌ها یا تغییر اکلوژن.</li>
<li><strong>لقی:</strong> در مرحلهٔ پیشرفته حرکت دندان؛ نشان می‌دهد استخوان پشتیبان کم شده است.</li>
</ul>
<h2>تفاوت ژنژیویت و پریودنتیت</h2>
<table>
<thead><tr><th></th><th>ژنژیویت (التهاب لثه)</th><th>پریودنتیت</th></tr></thead>
<tbody>
<tr><td>بافت درگیر</td><td>تنها لثه</td><td>لثه + بافت پیوندی + استخوان پشتیبان</td></tr>
<tr><td>از دست رفتن استخوان</td><td>نیست</td><td>هست</td></tr>
<tr><td>برگشت‌پذیری</td><td>با درمان و مراقبت مناسب تا اندازهٔ زیادی برمی‌گردد</td><td>استخوان از دست‌رفته خودبه‌خود بازنمی‌گردد؛ پیشرفت آن متوقف می‌شود</td></tr>
<tr><td>یافتهٔ معمول</td><td>خون‌ریزی، قرمزی، ورم</td><td>افزایش عمق پاکت، تحلیل، لقی</td></tr>
</tbody>
</table>
<p>این تفکیک با معاینه انجام می‌شود: عمق پاکت اندازه‌گیری می‌شود، لبهٔ لثه ارزیابی می‌گردد و در صورت لزوم با رادیوگرافی به سطح استخوان نگاه می‌شود. بر پایهٔ یک نشانهٔ تنها تصمیم گرفته نمی‌شود.</p>
<h2>عواملی که خطر را افزایش می‌دهند</h2>
<p>کنترل ناکافی پلاک عامل اصلی است. در کنار آن مصرف سیگار، دیابت کنترل‌نشده، برخی داروها، دوره‌های تغییر هورمونی، تنفس دهانی، لبه‌های نامناسب ترمیم و زمینهٔ ژنتیکی می‌توانند تصویر را سنگین‌تر کنند. در دورهٔ بارداری لثه آسان‌تر خون‌ریزی می‌کند؛ برای این دوره می‌توانید به صفحهٔ <a href="/fa/hamilelikte-dis-tedavisi/">درمان دندان در بارداری</a> نگاه کنید.</p>
<h2>درمان چگونه پیش می‌رود؟</h2>
<ol>
<li><strong>ارزیابی.</strong> اندازه‌گیری پاکت، شاخص خون‌ریزی، تحلیل، لقی و در صورت نیاز رادیوگرافی.</li>
<li><strong>درمان آغازین.</strong> جرم‌گیری و صاف‌کردن سطح ریشه؛ سامان‌دادن دوبارهٔ عادت‌های بهداشت دهان.</li>
<li><strong>ارزیابی دوباره.</strong> معمولاً چند هفته بعد پاسخ بافت سنجیده می‌شود. در بیشتر افراد همین مرحله کافی است.</li>
<li><strong>مرحلهٔ جراحی در صورت نیاز.</strong> اگر پاکت‌های عمیق بمانند گزینه‌های جراحی ارزیابی می‌شوند.</li>
<li><strong>دورهٔ نگهدارنده.</strong> معاینه با فاصله‌هایی که به‌صورت فردی تعیین می‌شود؛ بازگشت بیماری در همین مرحله گرفته می‌شود.</li>
</ol>
<p><strong>دربارهٔ آنتی‌بیوتیک:</strong> آنتی‌بیوتیک جای تمیزکردن مکانیکی پلاک و جرم زیر لثه را نمی‌گیرد. نیاز به آن جداگانه ارزیابی می‌شود.</p>
<h2>آنچه در خانه می‌توان کرد</h2>
<p>روزی دو بار مسواک‌زدن با مسواک نرم و رو به لبهٔ لثه، روزی یک بار تمیزکردن بین دندان‌ها (نخ یا مسواک بین‌دندانی)، ترک سیگار و پایبندی به فاصلهٔ معاینه. وقتی خون‌ریزی دیدید باید روش را اصلاح کرد نه مسواک‌زدن را کم؛ ناحیه‌ای که تمیز نشود التهاب را ادامه می‌دهد.</p>
<h2>پرسش‌های پرتکرار</h2>
<p><strong>آیا خون‌ریزی لثه خودبه‌خود برطرف می‌شود؟</strong><br>تا علتش از میان نرود برطرف نمی‌شود. تا زمانی که تجمع پلاک ادامه دارد التهاب هم ادامه می‌یابد. خون‌ریزی‌ای که در چند روز بهتر نشود باید ارزیابی گردد.</p>
<p><strong>آیا جرم‌گیری دندان‌ها را می‌ساید؟</strong><br>تمیزکردنی که با روش درست انجام شود بافت دندان را نمی‌ساید. حساسیتی که پس از آن احساس می‌شود به آشکارشدن سطح ریشه‌ای مربوط است که پیش‌تر با جرم پوشیده بود و معمولاً فروکش می‌کند.</p>
<p><strong>آیا لثهٔ تحلیل‌رفته بازمی‌گردد؟</strong><br>خودبه‌خود نه. در برخی گونه‌های تحلیل می‌توان گزینه‌های پوشش جراحی را ارزیابی کرد؛ تناسب به معاینه بستگی دارد.</p>
<p><strong>هر چند وقت باید برای معاینه بیایم؟</strong><br>فاصله به‌صورت فردی تعیین می‌شود. در کسانی که عوامل خطر دارند تواتر معاینه افزایش می‌یابد.</p>
<p>در کلینیک ما در محل اتصال بیلیک‌دوزو/اسن‌یورت، ترتیب درمان با انجام هم‌زمان ارزیابی لثه، اندازه‌گیری پاکت و تصویربرداری لازم تعیین می‌شود.</p>
<p><a href="/fa/agiz-dis-sagligi/">سلامت دهان و دندان</a> &middot; <a href="/fa/dis-curugu-kompozit-dolgu/">پوسیدگی دندان و ترمیم کامپوزیت</a> &middot; <a href="/fa/ilk-dis-muayenesi-tedavi-planlamasi/">نخستین معاینهٔ دندان</a> &middot; <a href="/fa/iletisim">نوبت و تماس</a></p>',
'خون‌ریزی لثه، قرمزی، تحلیل و بوی دهان چه معنایی دارند؟ تفاوت ژنژیویت و پریودنتیت، مراحل درمان و عوامل خطر.',
'FA' FROM blogs WHERE link = 'dis-eti-hastaliklarinin-erken-belirtileri-ve-tedavi-yontemleri';

INSERT INTO blogs_description (blog_id, title, description, seo_description, language)
SELECT id, 'بوی دهان چرا پدید می‌آید؟ علت‌ها و راه‌حل پایدار',
'<p>بوی دهان (هالیتوز) شکایتی رایج است و در بیشتر موارد منشأ آن درون دهان است. بو معمولاً از ترکیبات گوگردی فراری پدید می‌آید که باکتری‌ها هنگام تجزیهٔ بازمانده‌های پروتئینی می‌سازند. راه‌حل پایدار نه از پوشاندن بو بلکه از یافتن منشأ آن می‌گذرد.</p>
<h2>بوی صبحگاهی با بوی پایدار یکی نیست</h2>
<p>هنگام خواب جریان بزاق کم می‌شود و باکتری‌ها راحت‌تر زیاد می‌شوند؛ بویی که صبح احساس می‌شود از این رو عادی است و با مسواک‌زدن برطرف می‌گردد. اما بویی که در طول روز ادامه دارد و با مسواک‌زدن به‌روشنی کم نمی‌شود باید ارزیابی شود.</p>
<h2>علت‌های درون‌دهانی</h2>
<ul>
<li><strong>لایهٔ باکتریایی روی پشت زبان.</strong> بخش مهمی از بوهای با منشأ دهان از ناحیهٔ عقب زبان می‌آید.</li>
<li><strong>بیماری لثه.</strong> باکتری‌هایی که در پاکت‌های لثه جمع می‌شوند به بوی پایدار کمک می‌کنند. جزئیات: <a href="/fa/blog/dis-eti-hastaliklarinin-erken-belirtileri-ve-tedavi-yontemleri">نشانه‌های زودهنگام بیماری‌های لثه</a>.</li>
<li><strong>پوسیدگی‌ها و دندان‌های شکسته.</strong> در فضاهایی که تمیز نمی‌شوند غذا و باکتری جمع می‌گردد.</li>
<li><strong>ترمیم‌ها و پروتزهای نامتناسب.</strong> فاصله‌های لبه‌ای و سطوح تمیزنشدهٔ پروتز می‌توانند منشأ بو باشند.</li>
<li><strong>خشکی دهان.</strong> برخی داروها، تنفس دهانی و مصرف ناکافی مایعات بزاق را کم می‌کنند؛ بزاق پاک‌کنندهٔ طبیعی دهان است.</li>
<li><strong>دندان عقل نهفته یا نیمه‌رویش‌کرده.</strong> ناحیه‌ای که زیر لثه می‌ماند تمیزشدنی نیست. جزئیات: <a href="/fa/agiz-cerrahisi-uygulamalari/">اقدامات جراحی دهان</a>.</li>
</ul>
<h2>علت‌های خارج از دهان</h2>
<p>سینوزیت، سنگ لوزه، عفونت‌های دستگاه تنفسی فوقانی، رفلاکس و برخی وضعیت‌های متابولیک نیز می‌توانند بو ایجاد کنند. وقتی ارزیابی درون‌دهانی پاک درآید این احتمال‌ها مطرح می‌شوند و با رشتهٔ پزشکی مربوط بررسی می‌گردند.</p>
<h2>تغذیه و عادت‌ها</h2>
<p>بوی خوراکی‌هایی مانند سیر و پیاز چون از راه خون به ریه‌ها می‌رسد با مسواک‌زدن به‌کلی برطرف نمی‌شود؛ در چند ساعت خودبه‌خود کم می‌گردد. سیگار هم بوی خودش را می‌گذارد و هم خطر بیماری لثه را افزایش می‌دهد. در رژیم‌های بسیار کم‌کربوهیدرات بویی متفاوت در دهان احساس می‌شود.</p>
<h2>مسیری که در معاینه دنبال می‌شود</h2>
<table>
<thead><tr><th>مرحله</th><th>چه انجام می‌شود</th></tr></thead>
<tbody>
<tr><td>شرح حال</td><td>مدت بو، سیر آن در طول روز، داروهای مصرفی، خشکی دهان، سیگار و عادت‌های تغذیه</td></tr>
<tr><td>معاینهٔ درون دهان</td><td>وضعیت لثه، عمق پاکت، پوسیدگی‌ها، لبه‌های ترمیم، تطابق پروتز، پشت زبان</td></tr>
<tr><td>تصویربرداری</td><td>در صورت نیاز؛ در گمان به دندان نهفته، عفونت نوک ریشه یا پوسیدگی نادیدنی</td></tr>
<tr><td>ترتیب درمان</td><td>نخست منشأ التهاب و عفونت؛ سپس اصلاح ترمیمی نواحی تمیزنشدنی؛ پس از آن نظم مراقبت</td></tr>
</tbody>
</table>
<h2>آنچه برای راه‌حل پایدار می‌توان کرد</h2>
<ol>
<li>روزی دو بار مسواک‌زدن و روزی یک بار تمیزکردن بین دندان‌ها</li>
<li>تمیزکردن ملایم بخش عقب پشت زبان</li>
<li>کامل‌کردن درمان لثه و پایبندی به فاصلهٔ معاینه</li>
<li>برطرف‌کردن پوسیدگی، شکستگی و ترمیم‌های نامتناسبی که تمیزشدنی نیستند</li>
<li>مصرف کافی مایعات؛ اگر خشکی دهان ادامه دارد بررسی علت آن</li>
<li>ترک سیگار</li>
</ol>
<p>دهان‌شویه‌ها می‌توانند بو را کوتاه‌مدت بپوشانند اما علت را از میان نمی‌برند. مصرف طولانی برخی دهان‌شویه‌های الکل‌دار می‌تواند خشکی دهان را بیشتر کند.</p>
<h2>پرسش‌های پرتکرار</h2>
<p><strong>چرا بوی دهان خودم را نمی‌فهمم؟</strong><br>حس بویایی با بویی که پیوسته در معرض آن است خو می‌گیرد. از این رو بازخورد فردی نزدیک یا ارزیابی دندان‌پزشک قابل اتکاتر است.</p>
<p><strong>با اینکه مسواک می‌زنم بو ادامه دارد، چرا؟</strong><br>شاید مسواک به پشت زبان، پاکت‌های لثه و میان دندان‌ها به‌اندازهٔ کافی نمی‌رسد. پوسیدگی‌ای که تمیز نمی‌شود یا دندان نهفته هم می‌تواند منشأ باشد.</p>
<p><strong>آیا بوی دهان می‌تواند از معده باشد؟</strong><br>می‌تواند اما کمیاب‌تر از آن است که پنداشته می‌شود. نخست علت‌های درون‌دهانی ارزیابی می‌شوند.</p>
<p><strong>آیا باید از تمیزکنندهٔ زبان استفاده کنم؟</strong><br>تمیزکردن بخش عقب پشت زبان می‌تواند بو را کم کند. باید بدون فشار زیاد و بدون برانگیختن رفلکس تهوع انجام شود.</p>
<p>در کلینیک ما در محل اتصال بیلیک‌دوزو/اسن‌یورت، ارزیابی بوی دهان با بررسی هم‌زمان وضعیت لثه، پوسیدگی، لبه‌های ترمیم و پشت زبان انجام می‌شود.</p>
<p><a href="/fa/agiz-dis-sagligi/">سلامت دهان و دندان</a> &middot; <a href="/fa/ilk-dis-muayenesi-tedavi-planlamasi/">نخستین معاینهٔ دندان</a> &middot; <a href="/fa/iletisim">نوبت و تماس</a></p>',
'علت‌های درون‌دهانی و خارج‌دهانی بوی دهان، نقش زبان، خشکی دهان، تفاوت بوی صبحگاهی و بوی پایدار و مسیری که در معاینه دنبال می‌شود.',
'FA' FROM blogs WHERE link = 'agiz-kokusu-neden-olur--kalici-cozum-icin-neler-yapilabilir';

INSERT INTO blogs_description (blog_id, title, description, seo_description, language)
SELECT id, 'Hollywood Smile چیست؟ پشت این اصطلاح چه هست؟',
'<p>«Hollywood Smile» نام یک درمان پزشکی نیست. توصیفی رایج است برای ظاهری که از دندان‌های بسیار سفید، منظم و متقارن ساخته می‌شود. پشت آن یک اقدام واحد نیست؛ برنامه‌ریزی‌ای است که از فردی به فرد دیگر تغییر می‌کند. از این رو آغاز درست نه «انجام‌دادن Hollywood Smile» بلکه فهمیدن این است که با کدام اقدام‌ها چه چیزی تغییر خواهد کرد.</p>
<h2>این اصطلاح چه را در بر می‌گیرد؟</h2>
<ul>
<li>سفیدکردن دندان — اگر تنها تغییر رنگ هدف باشد. جزئیات: <a href="/fa/dis-beyazlatma/">سفیدکردن دندان</a></li>
<li>کاربردهای کامپوزیت — اصلاح‌های کوچک شکل، لبه و فاصله</li>
<li>لمینت (ونیر پرسلن)</li>
<li>روکش‌ها، برای نمونه <a href="/fa/zirkonyum-dis-kaplama/">روکش زیرکونیا</a></li>
<li>سامان‌دادن سطح لثه</li>
<li>درمان ارتودنسی — هنگامی که مشکل آرایش دندان‌ها علت اصلی است</li>
<li>جایگزینی دندان از دست‌رفته — <a href="/fa/dental-implant-tedavisi/">ایمپلنت دندانی</a></li>
</ul>
<p>همهٔ این اقدام‌ها با هم لازم نیستند. در برخی افراد تنها تمیزکردن و سفیدکردن کافی است؛ در برخی چون مشکل آرایش دندان‌ها اصلی است، به‌جای اقدام ترمیمی از درمان ارتودنسی سخن می‌رود.</p>
<h2>ظاهر طبیعی چگونه برنامه‌ریزی می‌شود؟</h2>
<p>نتیجهٔ طبیعی بیش از آنکه به سفیدی تک‌تک دندان‌ها مربوط باشد، به هماهنگی کل وابسته است. در برنامه‌ریزی این موارد با هم ارزیابی می‌شوند:</p>
<table>
<thead><tr><th>معیار</th><th>چرا مهم است</th></tr></thead>
<tbody>
<tr><td>خط چهره و لبخند</td><td>رابطهٔ لبهٔ دندان‌ها با خط لب پایین طبیعی‌بودن را تعیین می‌کند</td></tr>
<tr><td>خط میانی</td><td>رابطهٔ خط میانی دندان‌ها با خط میانی چهره</td></tr>
<tr><td>نسبت‌های دندان</td><td>نسبت طول به پهنای دندان‌های جلو نسبت به یکدیگر</td></tr>
<tr><td>سطح لثه</td><td>میزان لثه‌ای که هنگام لبخند دیده می‌شود و تقارن آن</td></tr>
<tr><td>رنگ و شفافیت</td><td>سفیدی یک‌دست مصنوعی دیده می‌شود؛ شفافیت در لبهٔ برنده طبیعی‌بودن می‌آورد</td></tr>
<tr><td>اکلوژن و عملکرد</td><td>نتیجهٔ زیبایی نباید جویدن و گفتار را مختل کند</td></tr>
</tbody>
</table>
<p>در مرحلهٔ برنامه‌ریزی می‌توان از عکس، اسکن دیجیتال و در صورت نیاز پروب موقتی در دهان بهره برد. هدف آن است که پیش از رفتن به اقدام قطعی، نتیجه با هم دیده شود. روند به‌تفصیل در صفحهٔ <a href="/fa/gulus-tasarimi/">طراحی لبخند فردی</a> توضیح داده شده است.</p>
<h2>نخست سلامت، سپس زیبایی</h2>
<p>اگر پوسیدگی، التهاب لثه، عفونت نوک ریشه یا مشکل اکلوژن باشد، اقدام زیبایی بر روی آن‌ها بنا نمی‌شود. در لبهٔ ترمیمی که هنگام ادامهٔ التهاب لثه انجام شود، تغییر رنگ و تحلیل در مدتی کوتاه دیده می‌شود. از این رو ترتیب چنین است: کنترل وضعیت اورژانسی و عفونت، درمان پایهٔ لثه و پوسیدگی، سپس مرحلهٔ زیبایی. برای کل روند <a href="/fa/tedavi-plani-ve-surec/">برنامهٔ درمان و روند آن</a>.</p>
<h2>پرسش‌هایی که پیش از تصمیم باید پرسید</h2>
<ul>
<li>در وضعیت من کدام اقدام‌ها پیشنهاد می‌شود و چرا؟</li>
<li>چه میزان تراش از بافت دندان لازم می‌شود؟ آیا بازگشت دارد؟</li>
<li>آیا گزینهٔ جایگزینی هست که از دست رفتن بافت کمتری بخواهد؟</li>
<li>آیا می‌توانم نتیجه را پیش از اقدام قطعی ببینم؟</li>
<li>پس از آن چه نظمی از مراقبت و معاینه لازم است؟</li>
<li>آیا می‌توانم دربارهٔ مادهٔ به‌کاررفته و آزمایشگاه اطلاع بگیرم؟</li>
</ul>
<h2>پرسش‌های پرتکرار</h2>
<p><strong>آیا برای Hollywood Smile حتماً روکش لازم است؟</strong><br>خیر. در برخی افراد سفیدکردن و اصلاح‌های کوچک کامپوزیت کافی‌اند. روکش چون تراش بیشتری از بافت می‌خواهد، پس از ارزیابی دیگر گزینه‌ها مطرح می‌شود.</p>
<p><strong>دندان‌ها چقدر باید سفید باشند؟</strong><br>معیار، ترجیح شخصی و ویژگی‌های چهره است. سفیدی یک‌دستی که با رنگ پوست و چشم هماهنگ نباشد مصنوعی دیده می‌شود.</p>
<p><strong>آیا نتیجه ماندگار است؟</strong><br>عمر ترمیم‌ها به تطابق لبه، بار اکلوزال، عادت فشردن دندان و مراقبت روزانه بستگی دارد. وعدهٔ مدت قطعی داده نمی‌شود؛ معاینهٔ منظم لازم است.</p>
<p><strong>آیا روند برای کسانی که از خارج می‌آیند متفاوت است؟</strong><br>برنامه‌ریزی همان است. چون میان مراحل زمان بهبودی و آزمایشگاه هست، تقویم از آغاز گفت‌وگو می‌شود.</p>
<p>در کلینیک ما در محل اتصال بیلیک‌دوزو/اسن‌یورت، برنامه‌ریزی زیبایی با ارزیابی هم‌زمان سلامت لثه، اکلوژن، بافت سالم باقی‌مانده و انتظار فرد انجام می‌شود.</p>
<p><a href="/fa/estetik/">دندان‌پزشکی زیبایی</a> &middot; <a href="/fa/gulus-tasarimi/">طراحی لبخند فردی</a> &middot; <a href="/fa/iletisim">نوبت و تماس</a></p>',
'Hollywood Smile نام درمان نیست بلکه توصیفی زیبایی‌شناختی است. چه اقدام‌هایی را در بر می‌گیرد، ظاهر طبیعی چگونه برنامه‌ریزی می‌شود، به چه باید توجه کرد؟',
'FA' FROM blogs WHERE link = 'hollywood-smile-nedir--mukemmel-guluse-giden-yol';

INSERT INTO blogs_description (blog_id, title, description, seo_description, language)
SELECT id, 'در نخستین معاینهٔ درمان ایمپلنت چه ارزیابی می‌شود؟',
'<p>تصمیم ایمپلنت تنها قراردادن یک پیچ به‌جای دندان از دست‌رفته نیست. نخستین معاینه ارزیابی‌ای است که وضعیت استخوان، سلامت لثه، اکلوژن، سابقهٔ عمومی سلامت و انتظار فرد را با هم در نظر می‌گیرد. تصمیم‌هایی که در این مرحله گرفته می‌شوند مستقیماً نتیجهٔ بلندمدت درمان را تعیین می‌کنند.</p>
<h2>معاینه با چه آغاز می‌شود؟</h2>
<p>گام نخست شنیدن شکایت و انتظار است: دندان کی از دست رفته، آیا پیش‌تر در آن ناحیه اقدامی انجام شده، آیا در جویدن دشواری هست، آیا نگرانی زیبایی وجود دارد. سپس سابقهٔ پزشکی گرفته می‌شود. بیماری‌های زمینه‌ای، داروهای مصرفی منظم، حساسیت‌ها و جراحی‌های پیشین پرسیده می‌شوند.</p>
<p>برخی گروه‌های دارویی و وضعیت‌های زمینه‌ای کنترل‌نشده می‌توانند برنامهٔ جراحی را تغییر دهند. از این رو برخی داروهای مصرفی در درمان پوکی استخوان، رقیق‌کننده‌های خون و دیابت کنترل‌نشده به‌ویژه پرسیده می‌شوند. هیچ دارویی را بیمار به تصمیم خود قطع نمی‌کند؛ در صورت نیاز نظر پزشک معالج گرفته می‌شود.</p>
<h2>ارزیابی درون دهان</h2>
<ul>
<li><strong>سلامت لثه.</strong> اگر التهاب فعال باشد پیش از جراحی ایمپلنت رسیدگی می‌شود.</li>
<li><strong>وضعیت دندان‌های مجاور.</strong> وجود پوسیدگی، شکستگی، ترمیم نشت‌دار یا عفونت نوک ریشه می‌تواند ترتیب را تغییر دهد.</li>
<li><strong>اندازهٔ فضا.</strong> پهنای ناحیهٔ بی‌دندان و فاصله تا دندان مقابل، اندازهٔ ایمپلنت قابل جای‌گذاری را تعیین می‌کند.</li>
<li><strong>ضخامت لثه و نوار لثهٔ چسبیده.</strong> برای سلامت بلندمدت لثه مهم است.</li>
<li><strong>رابطهٔ اکلوژن و جویدن.</strong> عادت دندان‌قروچه بار روی پروتز ایمپلنت را افزایش می‌دهد.</li>
<li><strong>بازشدن دهان.</strong> به‌ویژه در ناحیهٔ عقب بر دسترسی جراحی اثر می‌گذارد.</li>
<li><strong>عادت‌های بهداشت دهان و مصرف سیگار.</strong> بر بهبودی و نتیجهٔ بلندمدت تعیین‌کننده‌اند.</li>
</ul>
<h2>چرا تصویربرداری لازم است؟</h2>
<p>ارتفاع، پهنا و تراکم استخوان با چشم ارزیابی نمی‌شوند. افزون بر این بدون دانستن جایگاه کانال عصب در فک پایین و حفرهٔ سینوس در فک بالا نمی‌توان ایمن برنامه‌ریزی کرد. از این رو رادیوگرافی پانورامیک و در بیشتر موارد تصویربرداری سه‌بعدی خواسته می‌شود.</p>
<table>
<thead><tr><th>ثبت</th><th>چه نشان می‌دهد</th></tr></thead>
<tbody>
<tr><td>رادیوگرافی پانورامیک</td><td>نمای کلی، باقی‌مانده‌های ریشه، گمان به کیست، وضعیت دندان‌های مجاور</td></tr>
<tr><td>تصویربرداری سه‌بعدی</td><td>پهنا و تراکم استخوان، جایگاه کانال عصب و کف سینوس، اندازه‌گیری مقطعی</td></tr>
<tr><td>اسکن دیجیتال / مدل</td><td>رابطهٔ اکلوژن، جایگاهی که ایمپلنت از نظر پروتتیک باید در آن قرار گیرد</td></tr>
</tbody>
</table>
<p>برای هر بیماری به‌طور خودکار توموگرافی گرفته نمی‌شود. سهم تشخیصی مورد انتظار با میزان پرتوگیری با هم سنجیده می‌شود؛ اگر ثبت‌های موجود تازه و کافی باشند دوباره خواسته نمی‌شوند. این اصل به‌تفصیل در صفحهٔ <a href="/fa/ilk-dis-muayenesi-tedavi-planlamasi/">نخستین معاینهٔ دندان و برنامه‌ریزی درمان</a> توضیح داده شده است.</p>
<h2>برنامه‌ریزی از پروتز به عقب</h2>
<p>رویکرد درست آن است که ایمپلنت نه در جایی که استخوان بیشترین است، بلکه در جایی که پروتز باید بیاید قرار گیرد. از این رو برنامه‌ریزی از ظاهر نهایی و رابطهٔ جویدن آغاز می‌شود و به عقب می‌رود. اگر استخوان در آن جایگاه ناکافی باشد گزینه‌ها می‌توانند چنین باشند: ایمپلنتی با اندازهٔ متفاوت، جای‌گذاری زاویه‌دار، اقدام‌هایی که حجم استخوان را افزایش می‌دهند یا راه‌حل پروتتیک دیگری.</p>
<h2>آیا می‌توان بی‌درنگ ایمپلنت گذاشت؟</h2>
<p>در برخی موارد می‌توان ایمپلنت را در همان جلسهٔ کشیدن دندان قرار داد؛ در برخی موارد بهبود استخوان انتظار کشیده می‌شود. تصمیم به وجود عفونت، استواری دیواره‌های حفرهٔ کشیدن، کیفیت استخوان و پایداری اولیهٔ ایمپلنت بستگی دارد. گذاشتن دندان ثابت در همان روز نیز در هر موردی مناسب نیست.</p>
<h2>در پایان معاینه چه گفت‌وگو می‌شود؟</h2>
<ol>
<li>یافته‌های بالینی و نتیجهٔ تصویربرداری</li>
<li>رویکرد پیشنهادی و دلیل آن</li>
<li>گزینه‌های جایگزین (بریج، پروتز پارسیل، پیگیری فضا) و تفاوت‌هایشان</li>
<li>مراحل، شمار تقریبی جلسه‌ها و مدت‌های مورد انتظار برای بهبودی</li>
<li>خطرهای مهم و عوارض احتمالی</li>
<li>روند مورد انتظار در صورت انجام‌نشدن درمان</li>
<li>نظم مراقبت و معاینه پس از آن</li>
</ol>
<p>برای اینکه برنامه چگونه به‌صورت کتبی ارائه می‌شود و در صورت تغییر چگونه آگاه می‌شوید می‌توانید به صفحهٔ <a href="/fa/tedavi-plani-ve-surec/">برنامهٔ درمان و روند آن</a> نگاه کنید.</p>
<h2>پرسش‌های پرتکرار</h2>
<p><strong>اگر استخوانم ناکافی باشد ایمپلنت ممکن نیست؟</strong><br>ناکافی‌بودن به‌تنهایی مانع نیست. اقدام‌های افزایش حجم استخوان می‌توانند ارزیابی شوند؛ تناسب بر پایهٔ جای و میزان کمبود تعیین می‌گردد.</p>
<p><strong>هنگام آمدن به معاینه چه بیاورم؟</strong><br>رادیوگرافی و توموگرافی‌های پیشین در صورت وجود، فهرست داروهای مصرفی، اطلاعات بیماری و حساسیت شناخته‌شده. اگر پیش‌تر ایمپلنت انجام شده، کارت حاوی اطلاعات برند و اندازه.</p>
<p><strong>سیگار می‌کشم، آیا بر ارزیابی اثر دارد؟</strong><br>بله. سیگار می‌تواند بر بهبودی و نتیجهٔ بلندمدت اثر منفی بگذارد. این سرفصلی است که باید در برنامه‌ریزی آشکارا گفت‌وگو شود.</p>
<p><strong>آیا در یک جلسه تصمیم گرفته می‌شود؟</strong><br>بیشتر اوقات پس از تصویربرداری و ارزیابی آزمایشگاهی گفت‌وگوی دومی انجام می‌شود. اگر وضعیت اورژانسی نباشد، اختصاص زمان برای اندیشیدن امری مورد انتظار است.</p>
<p>در کلینیک ما در محل اتصال بیلیک‌دوزو/اسن‌یورت، ارزیابی ایمپلنت با انجام هم‌زمان معاینهٔ بالینی، تصویربرداری لازم و برنامه‌ریزی پروتتیک پیش برده می‌شود.</p>
<p><a href="/fa/dental-implant-tedavisi/">ایمپلنت دندانی</a> &middot; <a href="/fa/implant/">درمان ایمپلنت</a> &middot; <a href="/fa/iletisim">نوبت و تماس</a></p>',
'پیش از ایمپلنت، استخوان، لثه، اکلوژن و سابقهٔ پزشکی چگونه ارزیابی می‌شوند؟ کدام تصویربرداری و چرا خواسته می‌شود، چه چیزی تصمیم را تعیین می‌کند؟',
'FA' FROM blogs WHERE link = 'implant-tedavisinde-ilk-muayenede-neler-degerlendirilir';

INSERT INTO blogs_description (blog_id, title, description, seo_description, language)
SELECT id, 'در دورهٔ بهبودی پس از ایمپلنت به چه باید توجه کرد؟',
'<p>نتیجهٔ جراحی ایمپلنت تنها روی صندلی درمان تعیین نمی‌شود. مراقبت روزهای نخست، نظم تغذیه و پایبندی به معاینات مستقیماً بر روند یکپارچه‌شدن استخوان با ایمپلنت اثر می‌گذارند. این نوشته آنچه در دورهٔ بهبودی انتظار می‌رود و آنچه باید به آن توجه کرد را بازمی‌گوید؛ جای دستورهای فردی دندان‌پزشک شما را نمی‌گیرد.</p>
<h2>۲۴ ساعت نخست</h2>
<ul>
<li>به تامپونی که گذاشته شده تا مدتی که دندان‌پزشکتان می‌گوید به‌آرامی فشار دهید.</li>
<li>سرما از بیرون روی ناحیهٔ اقدام می‌تواند به کاهش ورم کمک کند.</li>
<li>روز نخست دهان را نشویید، تف نکنید و با نی ننوشید. این‌ها می‌توانند لخته را جابه‌جا کنند.</li>
<li>سیگار نکشید. سیگار از شناخته‌شده‌ترین عواملی است که بر بهبودی اثر منفی می‌گذارد.</li>
<li>با سر اندکی بالا استراحت کنید؛ از تلاش سنگین و کارهایی که خم‌شدن می‌خواهند بپرهیزید.</li>
<li>داروهایتان را بر پایهٔ نظمی که دندان‌پزشک داده مصرف کنید؛ به تصمیم خود چیزی نیفزایید و کم نکنید.</li>
</ul>
<h2>تغذیه</h2>
<p>در روزهای نخست خوراکی‌های نرم و ولرم ترجیح داده می‌شوند. نوشیدنی‌های بسیار داغ، خوراکی‌های سفت و ترد، خوراکی‌های دانه‌دار می‌توانند ناحیهٔ اقدام را آزار دهند. بردن جویدن به سمت دیگر دهان آسان‌ترین راه محافظت از ناحیه است. مصرف کافی مایعات به بهبودی کمک می‌کند؛ باید از الکل پرهیز کرد.</p>
<h2>بهداشت دهان</h2>
<p>کنارگذاشتن کامل مراقبت درست نیست؛ تجمع پلاک بهبودی را دشوار می‌کند. دیگر نواحی دهان به‌شکل عادی مسواک زده می‌شوند. ناحیهٔ اقدام اما از زمانی که دندان‌پزشکتان می‌گوید با مسواکی بسیار نرم و به‌آرامی تمیز می‌شود. استفاده از دهان‌شویه و زمان‌بندی آن را دندان‌پزشکتان تعیین می‌کند.</p>
<h2>چه طبیعی است و چه نه؟</h2>
<table>
<thead><tr><th>یافته</th><th>روند مورد انتظار</th><th>وضعیتی که باید با کلینیک تماس گرفت</th></tr></thead>
<tbody>
<tr><td>ورم</td><td>در ۲ تا ۳ روز نخست بیشتر می‌شود، سپس کم می‌گردد</td><td>ادامهٔ فزایندهٔ آن یا دشوارکردن بلع یا تنفس</td></tr>
<tr><td>درد</td><td>در روزهای نخست در سطحی که با داروی توصیه‌شده کنترل‌شدنی است</td><td>دردی که با وجود دارو بیشتر می‌شود یا شب از خواب بیدار می‌کند</td></tr>
<tr><td>خون‌ریزی به شکل نشت</td><td>در ساعت‌های نخست ممکن است باشد</td><td>خون‌ریزی فعالی که بند نمی‌آید</td></tr>
<tr><td>کبودی</td><td>در برخی افراد دیده می‌شود و خودبه‌خود برطرف می‌گردد</td><td>کبودی‌ای که به‌سرعت گسترش می‌یابد و با درد همراه است</td></tr>
<tr><td>تب</td><td>انتظار نمی‌رود</td><td>تب بالا، سستی، بوی یا مزهٔ بد</td></tr>
<tr><td>بی‌حسی</td><td>چند ساعت با اثر بی‌حس‌کننده</td><td>بی‌حسی لب، چانه یا زبان که روز بعد هم ادامه دارد</td></tr>
</tbody>
</table>
<h2>دورهٔ یکپارچه‌شدن (اسئواینتگریشن)</h2>
<p>یکپارچه‌شدن ایمپلنت با استخوان روندی زیستی است که هفته‌ها طول می‌کشد. مدت بر پایهٔ کیفیت استخوان، ناحیه‌ای که ایمپلنت در آن قرار گرفته، انجام‌شدن یا نشدن اقدام افزوده و پاسخ فردی بهبودی تغییر می‌کند. در این دوره مهم است که بار بیش از حد به ناحیه وارد نشود.</p>
<p>اگر از پروتز موقت استفاده می‌کنید، تطابق آن را دندان‌پزشکتان تنظیم می‌کند. اگر ناحیه‌ای فشار می‌آورد یا می‌خراشد نکوشید خودتان آن را درست کنید؛ برای معاینه بیایید. بارگذاری پیش از کامل‌شدن یکپارچگی می‌تواند بر نتیجه اثر منفی بگذارد.</p>
<h2>چه چیزی ایمپلنت را در بلندمدت حفظ می‌کند؟</h2>
<p>ایمپلنت پوسیده نمی‌شود، اما لثه و استخوان پیرامون آن می‌توانند بیمار شوند. این تصویر که به التهاب لثه در دندان طبیعی می‌ماند پیرامون ایمپلنت نیز دیده می‌شود و با پیشرفت، استخوان پشتیبان را کم می‌کند. راه محافظت تغییر نمی‌کند: تمیزکردن منظم و درست، تمیزکردن بین دندان‌ها، ترک سیگار و پایبندی به فاصلهٔ معاینه.</p>
<p>در کسانی که عادت فشردن و سایش دندان دارند نایت‌گارد می‌تواند مطرح شود. در معاینات، لثهٔ پیرامون ایمپلنت، شل‌شدن پیچ، سایش پروتز و رابطهٔ اکلوژن ارزیابی می‌شوند.</p>
<h2>پرسش‌های پرتکرار</h2>
<p><strong>بهبودی چقدر طول می‌کشد؟</strong><br>بهبود نخست بافت نرم میان چند روز تا چند هفته است؛ یکپارچه‌شدن با استخوان بیشتر طول می‌کشد. مدت دقیق فردی است و در معاینات ارزیابی می‌شود.</p>
<p><strong>آیا مصرف آنتی‌بیوتیک الزامی است؟</strong><br>ضرورت آن را دندان‌پزشک تعیین می‌کند. آنتی‌بیوتیک جای بهداشت و مراقبت پس از جراحی را نمی‌گیرد.</p>
<p><strong>آیا می‌توانم ورزش کنم؟</strong><br>فعالیت روزانهٔ سبک معمولاً مشکلی ایجاد نمی‌کند؛ تلاش سنگین، ورزش‌های برخوردی و حرکت‌هایی که خم‌شدن می‌خواهند در روزهای نخست به تعویق می‌افتند.</p>
<p><strong>احساس می‌کنم ایمپلنت تکان می‌خورد، طبیعی است؟</strong><br>خیر. اگر احساس حرکت هست باید بی‌درنگ برای معاینه آمد.</p>
<p><strong>بخیه‌ها کی کشیده می‌شوند؟</strong><br>بر پایهٔ نوع نخ به‌کاررفته تغییر می‌کند؛ برخی خودبه‌خود جذب می‌شوند. نوبت را دندان‌پزشکتان برنامه‌ریزی می‌کند.</p>
<p>در کلینیک ما در محل اتصال بیلیک‌دوزو/اسن‌یورت، فاصلهٔ معاینه پس از ایمپلنت با ارزیابی هم‌زمان اقدام انجام‌شده، وضعیت استخوان و پاسخ فردی بهبودی تعیین می‌شود.</p>
<p><a href="/fa/dental-implant-tedavisi/">ایمپلنت دندانی</a> &middot; <a href="/fa/agiz-cerrahisi-uygulamalari/">اقدامات جراحی دهان</a> &middot; <a href="/fa/iletisim">نوبت و تماس</a></p>',
'۲۴ ساعت نخست پس از ایمپلنت، تغذیه، بهداشت دهان و دورهٔ یکپارچه‌شدن. کدام یافته طبیعی است و در چه وضعیتی باید با کلینیک تماس گرفت؟',
'FA' FROM blogs WHERE link = 'implant-sonrasi-iyilesme-doneminde-nelere-dikkat-edilir';

INSERT INTO blogs_description (blog_id, title, description, seo_description, language)
SELECT id, 'لیفت سینوس چه زمانی می‌تواند لازم باشد؟',
'<p>پرتکرارترین مانع هنگام برنامه‌ریزی ایمپلنت در ناحیهٔ خلفی فک بالا، ناکافی‌بودن ارتفاع استخوان است. علت آن وجود حفرهٔ هوایی به نام سینوس ماگزیلاری بالای دندان و کم‌شدن استخوان این ناحیه به‌مرور پس از از دست رفتن دندان است. بالابردن کف سینوس (لیفت سینوس) اقدامی است که می‌کوشد حجم استخوان را افزایش دهد تا ایمپلنت ایمن جای گیرد.</p>
<h2>چرا استخوان در این ناحیه کم می‌شود؟</h2>
<p>پس از کشیدن دندان، استخوان آن ناحیه چون بار جویدنی که بر آن وارد می‌شد از میان رفته به‌مرور تحلیل می‌رود. در ناحیهٔ خلفی فک بالا افزون بر این، حفرهٔ سینوس می‌تواند رو به پایین گسترش یابد. وقتی دو عامل با هم جمع شوند، ارتفاع لازم برای ایمپلنت ممکن است نماند. از این رو مدتی که از از دست رفتن دندان گذشته اهمیت دارد.</p>
<h2>تصمیم چگونه گرفته می‌شود؟</h2>
<p>تنها با نگاه به رادیوگرافی پانورامیک تصمیم گرفته نمی‌شود. با تصویربرداری سه‌بعدی که اندازه‌گیری مقطعی را ممکن می‌کند، ارتفاع و پهنای استخوان باقی‌مانده و شکل کف سینوس ارزیابی می‌شود. همچنین به سالم‌بودن سینوس نگاه می‌شود؛ اگر سینوزیت فعال باشد اقدام به تعویق می‌افتد و نخست به این وضعیت رسیدگی می‌شود.</p>
<table>
<thead><tr><th>آنچه ارزیابی می‌شود</th><th>چرا مهم است</th></tr></thead>
<tbody>
<tr><td>ارتفاع استخوان باقی‌مانده</td><td>انتخاب روش و امکان انجام اقدام در همان جلسهٔ ایمپلنت را تعیین می‌کند</td></tr>
<tr><td>پهنای استخوان</td><td>حتی اگر ارتفاع کافی باشد، در ناکافی‌بودن پهنا اقدام افزوده لازم می‌شود</td></tr>
<tr><td>آناتومی کف سینوس</td><td>تیغه‌ها و نامنظمی‌ها برنامهٔ جراحی را تغییر می‌دهند</td></tr>
<tr><td>سلامت سینوس</td><td>اگر عفونت فعال یا سینوزیت مزمن باشد زمان‌بندی تغییر می‌کند</td></tr>
<tr><td>سلامت عمومی و سیگار</td><td>بر بهبودی و موفقیت اثر دارند</td></tr>
</tbody>
</table>
<h2>دو رویکرد اصلی</h2>
<p><strong>روش بسته (دسترسی کرستال).</strong> کف سینوس از حفره‌ای که ایمپلنت در آن جای می‌گیرد به‌صورت کنترل‌شده به بالا هل داده می‌شود. اگر ارتفاع استخوان باقی‌مانده بالاتر از سطحی معین باشد و پایداری اولیهٔ ایمپلنت تأمین شود، این روش ترجیح داده می‌شود. بیشتر اوقات در همان جلسهٔ ایمپلنت انجام می‌گیرد.</p>
<p><strong>روش باز (پنجرهٔ جانبی).</strong> با بازکردن پنجره‌ای از کنارهٔ استخوان، پردهٔ سینوس بالا برده می‌شود و در فضای پدیدآمده مادهٔ پیوند قرار می‌گیرد. هنگامی به کار می‌رود که استخوان باقی‌مانده کمتر باشد یا ناحیه‌ای گسترده لازم گردد. ایمپلنت می‌تواند در همان جلسه جای گیرد یا برای بلوغ استخوان انتظار کشیده شود.</p>
<p>اینکه کدام روش به کار رود بر پایهٔ اندازه‌گیری تعیین می‌شود؛ هیچ‌یک بر دیگری برتر نیست. برای جایگاه این اقدام در جراحی دهان می‌توانید به صفحهٔ <a href="/fa/agiz-cerrahisi-uygulamalari/">اقدامات جراحی دهان</a> نگاه کنید.</p>
<h2>دورهٔ بهبودی</h2>
<p>پس از اقدام چند روز ورم و حساسیت انتظار می‌رود. در این دوره باید بینی را با فشار پاک نکرد، هنگام عطسه دهان را باز نگه داشت، از نی استفاده نکرد و وضعیت‌هایی که تغییر فشار ایجاد می‌کنند مانند سفر هوایی را تا مدتی که دندان‌پزشک می‌گوید به تعویق انداخت. بر نکشیدن سیگار به‌ویژه تأکید می‌شود.</p>
<p>نشت خونی خفیف از بینی در روزهای نخست ممکن است دیده شود. در درد فزاینده، تب بالا، بوی بد، ادامهٔ گرفتگی یک‌طرفهٔ بینی یا ترشح از ناحیهٔ اقدام باید به کلینیک مراجعه کرد.</p>
<h2>آیا گزینهٔ جایگزینی هست؟</h2>
<p>لیفت سینوس در هر موردی تنها راه نیست. بر پایهٔ استخوان باقی‌مانده می‌توان گزینه‌هایی مانند به‌کاربردن ایمپلنت کوتاه‌تر، جای‌گذاری زاویه‌دار ایمپلنت، تکیه بر ناحیهٔ مجاور یا پروتز پارسیل به‌جای ثابت را ارزیابی کرد. هر گزینه شرط‌ها و مرزهای خود را دارد؛ تصمیم همراه با اندازه‌گیری و برنامهٔ پروتتیک گرفته می‌شود.</p>
<h2>پرسش‌های پرتکرار</h2>
<p><strong>آیا لیفت سینوس اقدامی دردناک است؟</strong><br>اقدام زیر بی‌حسی موضعی انجام می‌شود. پس از آن چند روز ورم و حساسیت انتظار می‌رود؛ هدف آن است که در سطحی کنترل‌شدنی بماند.</p>
<p><strong>پس از اقدام ایمپلنت چه زمانی انجام می‌شود؟</strong><br>اگر استخوان باقی‌مانده کافی باشد می‌تواند در همان جلسه جای گیرد. اگر کافی نباشد برای بلوغ پیوند مدتی معین انتظار کشیده می‌شود؛ این مدت بر پایهٔ فرد و مادهٔ به‌کاررفته تغییر می‌کند.</p>
<p><strong>سینوزیت دارم، آیا اقدام ممکن است؟</strong><br>هنگام وجود عفونت فعال انجام نمی‌شود. نخست به این وضعیت رسیدگی و انتظار کشیده می‌شود تا سینوس سالم گردد.</p>
<p><strong>مادهٔ پیوندی که به کار می‌رود چیست؟</strong><br>می‌تواند استخوان گرفته‌شده از خود فرد، پیوندهای استخوانی آماده یا کاربرد هم‌زمان آن‌ها باشد. اینکه کدام ماده به کار می‌رود و چرا برای شما توضیح داده می‌شود؛ حق پرسیدن دارید.</p>
<p><strong>اگر اقدام ناموفق باشد چه می‌شود؟</strong><br>هرچند کمیاب، پارگی پرده، عفونت یا نرسیدن پیوند به بلوغ مورد انتظار ممکن است دیده شود. در چنین وضعیت‌هایی انتظار، ارزیابی دوباره یا برنامهٔ پروتتیک متفاوتی گفت‌وگو می‌شود.</p>
<p>در کلینیک ما در محل اتصال بیلیک‌دوزو/اسن‌یورت، تصمیم بالابردن کف سینوس با ارزیابی هم‌زمان اندازه‌گیری سه‌بعدی، سلامت سینوس و برنامهٔ پروتتیک گرفته می‌شود.</p>
<p><a href="/fa/cerrahi/">جراحی دهان و فک</a> &middot; <a href="/fa/dental-implant-tedavisi/">ایمپلنت دندانی</a> &middot; <a href="/fa/iletisim">نوبت و تماس</a></p>',
'چرا در ناکافی‌بودن استخوان ناحیهٔ خلفی فک بالا کف سینوس بالا برده می‌شود؟ روش بسته و باز، قواعد بهبودی و گزینه‌های جایگزین.',
'FA' FROM blogs WHERE link = 'sinus-lifting-ne-zaman-gerekli-olabilir';

INSERT INTO blogs_description (blog_id, title, description, seo_description, language)
SELECT id, 'دندان عقل در چه وضعیت‌هایی کشیده می‌شود؟',
'<p>دندان‌های عقل (آسیای سوم) معمولاً از پایان نوجوانی تا آغاز دههٔ بیست شروع به رویش می‌کنند. هر دندان عقلی مشکل‌ساز نیست و هر دندان عقلی کشیده نمی‌شود. تصمیم بر پایهٔ جایگاه دندان، آسیبی که به بافت‌های پیرامون می‌زند و نشانه‌ها گرفته می‌شود.</p>
<h2>چرا می‌تواند مشکل‌ساز شود؟</h2>
<p>جایی که در استخوان فک برای این دندان‌ها در نظر گرفته شده در بیشتر افراد محدود است. دندانی که فضای کافی نیابد به‌کلی نمی‌روید، کج می‌ماند یا درون استخوان نهفته می‌ماند. پاکت لثهٔ پیرامون دندانی که نیمه‌رویش کرده تمیزشدنی نیست؛ باکتری‌هایی که آنجا جمع می‌شوند به التهاب می‌انجامند.</p>
<h2>وضعیت‌هایی که کشیدن در آن‌ها در نظر گرفته می‌شود</h2>
<ul>
<li>التهاب لثه، ورم و درد تکرارشونده (پری‌کرونیت)</li>
<li>پوسیدگی تمیزنشدنی در دندان عقل یا در دندان آسیای مجاور</li>
<li>فشار به ریشهٔ دندان مجاور به‌گونه‌ای که تحلیل ایجاد کند</li>
<li>پیدایش کیست یا آسیب‌شناسی دیگری در پیرامون آن</li>
<li>ایجاد پاکت لثهٔ عمیق و تمیزنشدنی در دندان مجاور</li>
<li>رویش در جایگاهی که به دندان مقابل یا گونه آسیب می‌زند</li>
<li>وضعیت‌هایی که درمان ارتودنسی یا پروتتیک برنامه‌ریزی‌شده می‌طلبد</li>
</ul>
<h2>وضعیت‌هایی که کشیدن لازم نیست</h2>
<p>دندان عقلی که به‌کلی روییده، با اکلوژن سازگار است، تمیزشدنی و بدون پوسیدگی است می‌تواند در دهان بماند. در دندان‌هایی که با وجود نهفته‌بودن نشانه‌ای نمی‌دهند و پیرامونشان آسیب‌شناسی ندارد، پیگیری ترجیح داده می‌شود. پیگیری به معنای «فراموش‌کردن» نیست: با فاصله‌های معین معاینهٔ بالینی و رادیوگرافیک انجام می‌گیرد.</p>
<p>باورهای رایجی مانند «دندان عقل همه باید کشیده شود» یا «دندان عقل دندان‌های جلو را کج می‌کند» به‌تنهایی دلیل کشیدن شمرده نمی‌شوند. تصمیم بر یافته‌های فردی استوار است.</p>
<h2>در ارزیابی به چه نگاه می‌شود؟</h2>
<table>
<thead><tr><th>معیار</th><th>چرا مهم است</th></tr></thead>
<tbody>
<tr><td>جایگاه و شیب دندان</td><td>دشواری جراحی و اثر آن بر دندان مجاور را تعیین می‌کند</td></tr>
<tr><td>شکل و شمار ریشه‌ها</td><td>برنامهٔ کشیدن را تغییر می‌دهد</td></tr>
<tr><td>نزدیکی به کانال عصب در فک پایین</td><td>برای ارزیابی خطر بی‌حسی؛ در صورت نیاز تصویربرداری سه‌بعدی خواسته می‌شود</td></tr>
<tr><td>رابطه با سینوس در فک بالا</td><td>بر رویکرد جراحی اثر می‌گذارد</td></tr>
<tr><td>وضعیت دندان مجاور</td><td>پوسیدگی، تحلیل ریشه یا وجود پاکت</td></tr>
<tr><td>سلامت عمومی و داروهای مصرفی</td><td>زمان‌بندی و برنامه‌ریزی جراحی</td></tr>
</tbody>
</table>
<h2>اقدام و بهبودی</h2>
<p>کشیدن زیر بی‌حسی موضعی انجام می‌شود. در دندان‌های نهفته ممکن است بالا بردن لثه و بیرون‌آوردن دندان به‌صورت تقسیم‌شده لازم باشد؛ این به معنای دشوارشدن اقدام نیست، انتخابی برای محافظت از بافت است.</p>
<p>در روزهای نخست ورم، محدودیت بازشدن دهان و حساسیت انتظار می‌رود. در این دوره سرما، تغذیهٔ نرم، نکشیدن سیگار و نشستن دهان در روز نخست توصیه می‌شود. دردی که با جداشدن لخته پدید می‌آید و معمولاً چند روز بعد بیشتر می‌شود معاینه می‌طلبد.</p>
<p>در درد فزاینده، تب بالا، دشواری بلع یا تنفس، خون‌ریزی‌ای که بند نمی‌آید یا بی‌حسی لب و چانه که روز بعد ادامه دارد باید بی‌درنگ به کلینیک مراجعه کرد. آنچه در ساعت‌های نخست باید کرد در صفحهٔ <a href="/fa/acil-dis-agrisinda-ilk-24-saat/">۲۴ ساعت نخست در درد اورژانسی دندان</a> توضیح داده شده است.</p>
<h2>زمان‌بندی</h2>
<p>کشیدن‌هایی که هنگام کامل‌نشدن رشد ریشه‌ها انجام می‌شوند معمولاً آسان‌تر پیش می‌روند و بهبودی می‌تواند سریع‌تر باشد. اما این به معنای آن نیست که هر دندان بدون نشانه‌ای باید در جوانی کشیده شود. تصمیم با سنجیدن سود مورد انتظار در برابر خطرهای اقدام گرفته می‌شود.</p>
<h2>پرسش‌های پرتکرار</h2>
<p><strong>آیا می‌توان دو طرف را در یک جلسه کشید؟</strong><br>در برخی موارد ممکن است. تصمیم بر پایهٔ جایگاه دندان‌ها، مدت مورد انتظار اقدام و وضعیت عمومی فرد گرفته می‌شود.</p>
<p><strong>آیا بی‌حسی پس از کشیدن ماندگار می‌شود؟</strong><br>در دندان‌های نزدیک به کانال عصب در فک پایین بی‌حسی گذرا ممکن است دیده شود؛ ماندگارشدن آن کمیاب است. خطر پیشاپیش با تصویربرداری ارزیابی و برای شما توضیح داده می‌شود.</p>
<p><strong>آیا در بارداری می‌توان کشید؟</strong><br>اقدام‌های جراحی غیراورژانسی معمولاً به تعویق می‌افتند. اگر وضعیت اورژانسی باشد زمان‌بندی و رویکرد جداگانه برنامه‌ریزی می‌شود؛ جزئیات در صفحهٔ <a href="/fa/hamilelikte-dis-tedavisi/">درمان دندان در بارداری</a> است.</p>
<p><strong>اگر نکشم چه می‌شود؟</strong><br>در دندانی که نشانه می‌دهد یا به دندان مجاور آسیب می‌زند، انتظار می‌تواند به پیشرفت پوسیدگی و از دست رفتن استخوان بینجامد. در دندان‌های بی‌نشانه اما پیگیری می‌تواند گزینه‌ای مناسب باشد.</p>
<p>در کلینیک ما در محل اتصال بیلیک‌دوزو/اسن‌یورت، تصمیم دندان عقل با در نظر گرفتن هم‌زمان معاینهٔ بالینی، ارزیابی رادیوگرافیک و وضعیت دندان‌های مجاور گرفته می‌شود.</p>
<p><a href="/fa/agiz-cerrahisi-uygulamalari/">اقدامات جراحی دهان</a> &middot; <a href="/fa/cerrahi/">جراحی دهان و فک</a> &middot; <a href="/fa/iletisim">نوبت و تماس</a></p>',
'دندان عقل در چه وضعیت‌هایی کشیده می‌شود و در چه وضعیت‌هایی پیگیری می‌گردد؟ معیارهای ارزیابی، اقدام، بهبودی و زمان‌بندی.',
'FA' FROM blogs WHERE link = 'yirmi-yas-disi-hangi-durumlarda-cekilir';

INSERT INTO blogs_description (blog_id, title, description, seo_description, language)
SELECT id, 'آیا پس از درمان ریشه همیشه روکش لازم است؟',
'<p>پرتکرارترین پرسش دربارهٔ دندانی که درمان ریشه‌اش به پایان رسیده این است: «آیا حالا حتماً باید روکش بگذارم؟» پاسخ کوتاه، خیر است. روکش ادامهٔ خودکار درمان ریشه نیست. تصمیم بر پایهٔ جایگاه دندان در دهان، میزان بافت سالم باقی‌مانده، بار اکلوزال و خطر شکستن گرفته می‌شود.</p>
<h2>پرسش اصلی «ریشه» نیست، «چقدر بافت مانده» است</h2>
<p>درمان ریشه به بافت درون دندان مربوط است. آنچه دندان را شکننده می‌کند بیشتر اوقات خود درمان نیست، بلکه بافتی است که تا رسیدن به آن از دست رفته: پوسیدگی عمیق، ترمیم قدیمی و بزرگ، شکستگی یا سایش. هرچه دیواره‌های دندان نازک‌تر شده باشند، خطر شکافتن آن هنگام جویدن بیشتر است.</p>
<p>از این رو ارزیابی نه به خود درمان ریشه بلکه به بافت باقی‌ماندهٔ دندان می‌نگرد. صفحهٔ <a href="/fa/dis-curugu-kompozit-dolgu/">پوسیدگی دندان و ترمیم کامپوزیت</a> می‌تواند در فهم چگونگی پیشروی پوسیدگی و آنچه از میان می‌برد کمک کند.</p>
<h2>دندان‌های عقب با دندان‌های جلو یکی نیستند</h2>
<p>دندان‌های آسیای بزرگ و کوچک بار اصلی جویدن را بر دوش دارند. در این ناحیه نیرو می‌کوشد دندان را به پهلوها بشکافد؛ در دندان عقبی که دیواره‌هایش ضعیف شده، ترمیمی پوشاننده (انله یا روکش) بیشتر اوقات مطرح می‌شود.</p>
<p>در دندان‌های جلو اما بار کمتر است و حفرهٔ دسترسی کوچک. اگر بافت باقی‌مانده کافی باشد، ترمیم کامپوزیت خوب‌ساخته می‌تواند مدتی طولانی کار کند. تصمیم روکش در دندان جلو بیشتر اوقات نه از خطر شکستن بلکه از انتظار رنگ و شکل زاده می‌شود.</p>
<h2>گزینه‌ها و جای مناسب آن‌ها</h2>
<table>
<thead><tr><th>ترمیم</th><th>چه زمانی در نظر گرفته می‌شود</th><th>نکتهٔ مورد توجه</th></tr></thead>
<tbody>
<tr><td>ترمیم کامپوزیت</td><td>دیواره‌های باقی‌مانده سالم، از دست رفتن ماده محدود، بار کم</td><td>گزینه‌ای که کمترین از دست رفتن بافت را می‌خواهد؛ در از دست رفتن‌های گسترده کافی نیست</td></tr>
<tr><td>انله / ترمیم پوشانندهٔ بخشی</td><td>یک یا دو دیواره ضعیف است، نیاز به محافظت از کاسپ‌ها هست</td><td>بدون تراش به‌اندازهٔ روکش، پوشش را فراهم می‌کند</td></tr>
<tr><td>روکش</td><td>بیشتر دیواره‌ها از میان رفته، نشانهٔ ترک هست، بار بالاست</td><td>بافت بیشتری تراشیده می‌شود؛ بازگشت ندارد</td></tr>
<tr><td>پست (تکیه‌گاه درون کانال)</td><td>اگر بافتی برای نگه‌داشتن ترمیم رویی نمانده باشد</td><td>دندان را تقویت نمی‌کند؛ تنها گیر فراهم می‌آورد و کاربرد بی‌مورد آن می‌تواند خطر شکستگی ریشه را افزایش دهد</td></tr>
</tbody>
</table>
<p>وقتی روکش مطرح می‌شود، انتخاب ماده موضوعی جداست؛ در صفحهٔ <a href="/fa/zirkonyum-dis-kaplama/">روکش زیرکونیا</a> بررسی می‌گردد.</p>
<h2>سرفصل‌های دیگری که بر تصمیم اثر می‌گذارند</h2>
<ul>
<li><strong>نشانهٔ ترک.</strong> اگر گمان به ترک در دندان باشد، زودتر به ترمیم پوشاننده رفته می‌شود.</li>
<li><strong>فشردن و سایش.</strong> در کسانی که شب دندان می‌فشارند بار به‌شدت افزایش می‌یابد؛ نایت‌گارد نیز می‌تواند بخشی از برنامه باشد.</li>
<li><strong>نقش دندان در برنامه.</strong> دندانی که پایهٔ بریج خواهد شد یا به پروتز پارسیل تکیه می‌دهد محافظه‌کارانه‌تر ترمیم می‌شود.</li>
<li><strong>پشتیبانی لثه و استخوان.</strong> اگر بافت پشتیبان ضعیف باشد برنامهٔ ترمیم تغییر می‌کند.</li>
<li><strong>رابطهٔ اکلوژن.</strong> چگونگی تماس با دندان مقابل توزیع بار را تعیین می‌کند.</li>
</ul>
<h2>زمان‌بندی</h2>
<p>پس از پایان درمان ریشه، دندان تا ترمیم قطعی با ترمیمی موقت بسته می‌شود. اگر این انتظار بیش از اندازه طول بکشد دو خطر پدید می‌آید: نشت از لبهٔ ترمیم موقت و شکستن دندان ضعیف هنگام جویدن. از این رو به تعویق نینداختن ترمیم قطعی اهمیت دارد.</p>
<p>در برخی دندان‌ها برای پیگیری بهبودی انتظاری کوتاه ترجیح داده می‌شود. در چنین وضعیتی آشکارا به شما گفته می‌شود چرا انتظار کشیده می‌شود و چه زمانی ادامه می‌یابد. کل روند در صفحهٔ <a href="/fa/tedavi-plani-ve-surec/">برنامهٔ درمان و روند آن</a> است.</p>
<h2>پس از آن به چه توجه شود؟</h2>
<p>دندانی که درمان ریشه شده می‌تواند بپوسد؛ چون پالپ ندارد هشدار درد نمی‌آید و مشکل بی‌صدا پیش می‌رود. از این رو معاینهٔ منظم و تمیزکردن بین دندان‌ها اهمیت دارد. عادت‌هایی مانند شکستن پوستهٔ سفت با دندان و جویدن یخ خطر شکستن را افزایش می‌دهند.</p>
<h2>پرسش‌های پرتکرار</h2>
<p><strong>آیا دندانی که درمان ریشه شده حتماً تیره می‌شود؟</strong><br>خیر. تغییر رنگ در هر دندانی دیده نمی‌شود؛ می‌تواند با سابقهٔ ضربه و باقی‌مانده‌های درون کانال مرتبط باشد. اگر دیده شود، سفیدکردن درون‌دندانی یا گزینه‌های ترمیمی ارزیابی می‌گردند.</p>
<p><strong>آیا درست است که وقتی ترمیم کافی است روکش پیشنهاد شود؟</strong><br>پیشنهاد باید همراه با دلیلش توضیح داده شود. حق دارید بپرسید: «دیواره‌های باقی‌ماندهٔ من در چه وضعی‌اند، آیا گزینه‌ای هست که بافت کمتری بتراشد؟»</p>
<p><strong>آیا گذاشتن پست دندان را تقویت می‌کند؟</strong><br>خیر. پست تنها برای گیر ترمیم رویی به کار می‌رود؛ دندان را مقاوم نمی‌کند و اگر بی‌مورد به کار رود می‌تواند زیان بزند.</p>
<p><strong>آیا پس از گذاشتن روکش دندان دیگر مشکلی ایجاد نمی‌کند؟</strong><br>روکش دندان را در برابر شکستن محافظت می‌کند، اما از لبهٔ آن می‌تواند پوسیدگی پدید آید و بافت‌های پشتیبان بیمار شوند. نیاز به مراقبت و معاینه ادامه دارد.</p>
<p><strong>درمان ریشه‌ام تمام شد اما هنوز حساسیت خفیفی هست، طبیعی است؟</strong><br>در روزهای نخست حساسیت هنگام جویدن ممکن است باشد. اگر درد فزاینده، ورم یا تب باشد باید بی‌درنگ به کلینیک مراجعه کرد.</p>
<p>در کلینیک ما در محل اتصال بیلیک‌دوزو/اسن‌یورت، نوع ترمیم پس از درمان ریشه با ارزیابی هم‌زمان بافت سالم باقی‌مانده، گروه دندان، خطر ترک و بار اکلوزال برگزیده می‌شود.</p>
<p><a href="/fa/kanal-tedavisi/">درمان ریشه</a> &middot; <a href="/fa/agiz-dis-sagligi/">سلامت دهان و دندان</a> &middot; <a href="/fa/iletisim">نوبت و تماس</a></p>',
'پس از درمان ریشه، ترمیم یا روکش؟ تصمیم را بافت سالم باقی‌مانده، گروه دندان و بار اکلوزال تعیین می‌کنند. گزینه‌ها و زمان‌بندی.',
'FA' FROM blogs WHERE link = 'kanal-tedavisi-sonrasi-kaplama-her-zaman-gerekir-mi';

INSERT INTO blogs_description (blog_id, title, description, seo_description, language)
SELECT id, 'حساسیت پس از سفیدکردن دندان چگونه مدیریت می‌شود؟',
'<p>حساسیت گذرا به سرد و گرم پس از سفیدکردن، پرتکرارترین اثر این کاربرد است. در بیشتر افراد در مدتی کوتاه فروکش می‌کند و کنارگذاشتن درمان را نمی‌طلبد. مهم آن است که بدانیم حساسیت چرا پدید می‌آید و پیش از اقدام بر همان پایه برنامه‌ریزی کنیم.</p>
<h2>حساسیت چرا پدید می‌آید؟</h2>
<p>مادهٔ سفیدکننده به درون مینا و عاج نفوذ می‌کند و مولکول‌های رنگی را تغییر می‌دهد. در این نفوذ، حرکت مایع درون عاج برانگیخته می‌شود و بافت عصبی دندان آن را به‌عنوان محرکی کوتاه درک می‌کند. اثر معمولاً هنگام اجرا یا بی‌درنگ پس از آن آغاز می‌شود و در چند ساعت یا چند روز کم می‌گردد.</p>
<p>این تصویر نشانهٔ آسیب ماندگار در دندان نیست. اما مدت و شدت آن از فردی به فرد دیگر تغییر می‌کند؛ در برخی افراد اصلاً دیده نمی‌شود.</p>
<h2>وضعیت‌هایی که خطر را افزایش می‌دهند</h2>
<ul>
<li>سطح ریشهٔ آشکار و تحلیل لثه</li>
<li>سایش مینا، ترک یا نقص‌های گوه‌ای</li>
<li>پوسیدگی درمان‌نشده یا ترمیم نشت‌دار</li>
<li>التهاب فعال لثه</li>
<li>سابقهٔ حساسیت پیشین</li>
<li>کاربرد ژل بیش از اندازه یا طولانی‌تر از توصیه</li>
<li>سرریزشدن ژل به لثه به‌دلیل پلاک نامتناسب</li>
</ul>
<p>از این رو پیش از سفیدکردن معاینه انجام می‌شود؛ اگر پوسیدگی، ترمیم نشت‌دار و مشکلات لثه باشد نخست به آن‌ها رسیدگی می‌گردد. کل ارزیابی تناسب در صفحهٔ <a href="/fa/dis-beyazlatma/">سفیدکردن دندان</a> است.</p>
<h2>تدابیری که پیش از اقدام می‌توان گرفت</h2>
<table>
<thead><tr><th>تدبیر</th><th>هدف آن</th></tr></thead>
<tbody>
<tr><td>معاینه و درمان‌های آماده‌سازی</td><td>برطرف‌کردن نخستِ پوسیدگی، ترمیم نشت‌دار و التهاب لثه</td></tr>
<tr><td>پرسیدن سابقهٔ حساسیت</td><td>تنظیم فردی دوز، مدت و فاصلهٔ جلسه‌ها</td></tr>
<tr><td>ساخت پلاک مناسب</td><td>جلوگیری از سرریزشدن ژل به لثه</td></tr>
<tr><td>فرآورده‌های پشتیبان توصیه‌شده از سوی دندان‌پزشک</td><td>کاستن از تحریک کانال‌های عاجی</td></tr>
<tr><td>تقویمی واقع‌بینانه</td><td>پیشگیری از افزایش دوز برای نتیجهٔ سریع</td></tr>
</tbody>
</table>
<h2>اگر حساسیت آغاز شد چه کنیم؟</h2>
<ol>
<li><strong>اجرا را موقتاً متوقف کنید.</strong> یک یا چند روز توقف بیشتر اوقات کافی است؛ مدت کل بر همان پایه دوباره برنامه‌ریزی می‌شود.</li>
<li><strong>دوز را خودتان افزایش ندهید.</strong> بیشترکردن ژل یا طولانی‌کردن مدت حساسیت را تشدید می‌کند.</li>
<li><strong>از نوشیدنی‌های بسیار گرم و بسیار سرد دوری کنید.</strong> مصرف ولرم در روزهای نخست راحت‌تر است.</li>
<li><strong>خمیردندان و فرآورده‌هایی را که دندان‌پزشکتان توصیه کرده به کار ببرید.</strong> به تصمیم خود فرآورده نیفزایید.</li>
<li><strong>مسواک نرم و روش ملایم به کار ببرید.</strong> مسواک‌زدن سخت، حساسیت را روی سطح ریشهٔ آشکار افزایش می‌دهد.</li>
<li><strong>خوراکی‌های اسیدی را محدود کنید.</strong> در این دوره سطح مینا حساس‌تر است.</li>
</ol>
<h2>چه زمانی با کلینیک تماس بگیرید؟</h2>
<p>اگر حساسیت در چند روز کم نمی‌شود، فزاینده ادامه می‌یابد یا به دردی خودبه‌خودی و شبانه تبدیل می‌گردد، ارزیابی لازم است. ناحیه‌ای سفید یا قرمز در لثه که بهبود نمی‌یابد، دردی تیز که در یک دندان متمرکز است و دردی که هنگام جویدن پدید می‌آید نیز بیرون از تصویر مورد انتظارند. در چنین وضعیت‌هایی پوسیدگی، ترک یا مشکل پالپ زمینه‌ای ممکن است باشد.</p>
<h2>نتیجه و پایداری رنگ</h2>
<p>در روزهای نخست محدودکردن نوشیدنی و خوراکی‌های تیره توصیه می‌شود. بازگشت جزئی سایه در گذر زمان عادی است؛ نیاز به ترمیم رنگ در معاینهٔ پیگیری تعیین می‌گردد. فراموش نکنید که سفیدکردن تنها بر بافت طبیعی دندان اثر می‌گذارد و رنگ ترمیم‌ها و روکش‌های موجود تغییر نمی‌کند — این موضوع در <a href="/fa/blog/hollywood-smile-nedir--mukemmel-guluse-giden-yol">نوشتهٔ برنامه‌ریزی زیبایی</a> نیز بررسی می‌شود.</p>
<h2>پرسش‌های پرتکرار</h2>
<p><strong>حساسیت چند روز طول می‌کشد؟</strong><br>در بیشتر افراد میان چند ساعت تا چند روز است. در صورت طولانی‌شدن یا افزایش، معاینه لازم است.</p>
<p><strong>اگر حساسیت پدید آید باید سفیدکردن را کنار بگذارم؟</strong><br>معمولاً خیر. با توقف موقت و تنظیم دوبارهٔ دوز و مدت می‌توان ادامه داد؛ تصمیم در معاینهٔ پیگیری گرفته می‌شود.</p>
<p><strong>آیا می‌توانم مسکن مصرف کنم؟</strong><br>مصرف دارو با مشورت دندان‌پزشکتان تعیین می‌شود. ادامهٔ درد بیش از آنکه وضعیتی باشد که باید با دارو سرکوب شود، یافته‌ای است که باید ارزیابی گردد.</p>
<p><strong>حساسیت دارم، آیا اصلاً نمی‌توانم سفید کنم؟</strong><br>در بیشتر موارد قابل ارزیابی است. نخست علت حساسیت بررسی می‌شود؛ اگر سطح ریشهٔ آشکار، ترک یا پوسیدگی باشد برطرف می‌گردد و پروتکل بر همان پایه تنظیم می‌شود.</p>
<p><strong>کدام حساسیت کمتری ایجاد می‌کند، خانگی یا کلینیکی؟</strong><br>قاعدهٔ واحدی نیست. در هر دو، دوز، مدت و پاسخ فردی تعیین‌کننده‌اند؛ روش بر پایهٔ یافتهٔ معاینه برگزیده می‌شود.</p>
<p>در کلینیک ما در محل اتصال بیلیک‌دوزو/اسن‌یورت، پروتکل سفیدکردن با ارزیابی هم‌زمان سابقهٔ حساسیت، سلامت لثه و وضعیت سطح ریشهٔ آشکار تعیین می‌شود.</p>
<p><a href="/fa/dis-beyazlatma/">سفیدکردن دندان</a> &middot; <a href="/fa/estetik/">دندان‌پزشکی زیبایی</a> &middot; <a href="/fa/agiz-dis-sagligi/">سلامت دهان و دندان</a> &middot; <a href="/fa/iletisim">نوبت و تماس</a></p>',
'چرا پس از سفیدکردن حساسیت به سرد و گرم پدید می‌آید، چه چیزی خطر را افزایش می‌دهد، چگونه مدیریت می‌شود؟ چه زمانی باید با کلینیک تماس گرفت؟',
'FA' FROM blogs WHERE link = 'dis-beyazlatma-sonrasi-hassasiyet-nasil-yonetilir';

